require_once '../../config/auth.php'; require_once '../../config/database.php'; requireOsisMember();
$userId=(int)($_SESSION['user_id']??0); $today=date('Y-m-d');
$q=$pdo->prepare("SELECT om.id,om.bagian,s.id student_id,s.nama_lengkap,c.nama_kelas,op.nama_jabatan,ay.tahun_ajaran FROM osis_members om JOIN students s ON s.id=om.student_id LEFT JOIN classes c ON c.id=s.kelas_id JOIN osis_positions op ON op.id=om.position_id JOIN academic_years ay ON ay.id=om.academic_year_id WHERE s.user_id=? AND om.status='aktif' AND ay.status='aktif' ORDER BY om.id DESC LIMIT 1"); $q->execute([$userId]); $profile=$q->fetch(PDO::FETCH_ASSOC)?:[];
$memberId=(int)($profile['id']??0); $studentId=(int)($profile['student_id']??0); $name=$profile['nama_lengkap']??($_SESSION['username']??'Anggota OSIS'); $position=$profile['nama_jabatan']??($_SESSION['jabatan']??'Anggota OSIS');
$totalMembers=(int)$pdo->query("SELECT COUNT(*) FROM osis_members WHERE status='aktif'")->fetchColumn(); $totalActivities=(int)$pdo->query("SELECT COUNT(*) FROM activities WHERE status IN ('rencana','berlangsung')")->fetchColumn(); $totalAnnouncements=(int)$pdo->query("SELECT COUNT(*) FROM announcements WHERE status='publish' AND target IN ('semua','osis')")->fetchColumn();
$news=$pdo->query("SELECT judul,isi,tanggal_publish FROM announcements WHERE status='publish' AND target IN ('semua','osis') ORDER BY tanggal_publish DESC LIMIT 3")->fetchAll(PDO::FETCH_ASSOC);
$q=$pdo->prepare("SELECT a.nama_kegiatan,a.tanggal_mulai,a.lokasi,a.status,ac.jabatan_panitia FROM activities a LEFT JOIN activity_committees ac ON ac.activity_id=a.id AND ac.osis_member_id=? WHERE a.status IN ('rencana','berlangsung') ORDER BY (a.tanggal_mulai<?),a.tanggal_mulai LIMIT 4"); $q->execute([$memberId,$today]); $activities=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$pdo->prepare("SELECT d.nominal,d.frekuensi,d.bulan,d.minggu_ke,d.tanggal_selesai,p.status payment_status FROM student_dues d LEFT JOIN student_due_payments p ON p.student_due_id=d.id AND p.student_id=? WHERE d.jenis_kas='osis' AND d.status='aktif' AND d.tahun=YEAR(CURDATE()) ORDER BY CASE WHEN d.tanggal_selesai>=CURDATE() THEN 0 ELSE 1 END,d.tanggal_selesai DESC,d.id DESC LIMIT 1"); $q->execute([$studentId]); $cash=$q->fetch(PDO::FETCH_ASSOC)?:null; $cashPaid=$cash&&$cash['payment_status']==='lunas';
$pageTitle='Dashboard Anggota OSIS'; require_once '../../includes/header.php'; require_once '../../includes/osis_sidebar.php'; ?>
