<section class="member-home-hero"><div><span class="member-home-kicker"><i class="bi bi-stars"></i> Portal Organisasi</span><h1>Halo, <?= htmlspecialchars(explode(' ',trim($name))[0]) ?>!</h1><p>Setiap ide dan kontribusi Anda membantu OSIS menjadi lebih bermakna. Mari lanjutkan hal baik hari ini.</p><span class="member-home-role"><i class="bi bi-patch-check-fill"></i><?= htmlspecialchars($position) ?><?= !empty($profile['bagian'])?' · '.htmlspecialchars($profile['bagian']):'' ?></span></div><div class="member-home-profile"><b><?= htmlspecialchars(strtoupper(substr($name,0,1))) ?></b><strong><?= htmlspecialchars($name) ?></strong><small><i class="bi bi-building"></i> <?= htmlspecialchars($profile['nama_kelas']??'Kelas belum tercatat') ?></small><em>Anggota aktif</em></div></section>
<section class="member-home-stat-grid"><article><i class="blue bi bi-people-fill"></i><div><small>Tim OSIS aktif</small><strong><?= $totalMembers ?></strong><p>anggota dalam organisasi</p></div></article><article><i class="teal bi bi-calendar2-check-fill"></i><div><small>Agenda berjalan</small><strong><?= $totalActivities ?></strong><p>kegiatan siap dijalankan</p></div></article><article><i class="amber bi bi-megaphone-fill"></i><div><small>Informasi OSIS</small><strong><?= $totalAnnouncements ?></strong><p>pengumuman tersedia</p></div></article></section>
<section class="member-home-grid"><article class="member-home-card member-agenda-card"><header><div><span>Agenda terdekat</span><h3>Yang perlu Anda siapkan</h3></div><i class="bi bi-calendar-event"></i></header><div class="member-agenda-list"><?php foreach($activities as $a): ?><div><time><b><?= date('d',strtotime($a['tanggal_mulai'])) ?></b><small><?= strtoupper(date('M',strtotime($a['tanggal_mulai']))) ?></small></time><p><strong><?= htmlspecialchars($a['nama_kegiatan']) ?></strong><span><i class="bi bi-geo-alt"></i> <?= htmlspecialchars($a['lokasi']?:'Lokasi menyusul') ?> · <?= date('H:i',strtotime($a['tanggal_mulai'])) ?> WIB</span><?php if($a['jabatan_panitia']): ?><em><?= htmlspecialchars($a['jabatan_panitia']) ?></em><?php endif ?></p><label class="<?= htmlspecialchars($a['status']) ?>"><?= htmlspecialchars(ucfirst($a['status'])) ?></label></div><?php endforeach; if(!$activities): ?><aside class="member-empty"><i class="bi bi-calendar-x"></i><strong>Belum ada agenda terjadwal</strong><span>Agenda OSIS berikutnya akan muncul di sini.</span></aside><?php endif ?></div></article>
<div class="member-home-side"><article class="member-home-card member-cash-card <?= $cashPaid?'paid':'' ?>"><header><div><span>Status kas OSIS</span><h3><?= $cashPaid?'Kas sudah lunas':'Cek kas Anda' ?></h3></div><i class="bi <?= $cashPaid?'bi-check2-circle':'bi-wallet2' ?>"></i></header><b>Rp <?= $cash?number_format((float)$cash['nominal'],0,',','.'):'—' ?></b><p><?= $cash?($cash['frekuensi']==='mingguan'?'Minggu ke-'.(int)$cash['minggu_ke']:'Kas bulan '.date('F',mktime(0,0,0,(int)$cash['bulan'],1))):'Tagihan kas belum diterbitkan.' ?></p><small><i class="bi <?= $cashPaid?'bi-check-circle-fill':'bi-info-circle-fill' ?>"></i> <?= $cashPaid?'Pembayaran telah tercatat':'Silakan konfirmasi ke bendahara' ?></small></article><article class="member-home-card member-profile-card"><header><div><span>Identitas organisasi</span><h3>Profil keanggotaan</h3></div><i class="bi bi-person-vcard"></i></header><p><i class="bi bi-person-badge"></i> Jabatan <b><?= htmlspecialchars($position) ?></b></p><p><i class="bi bi-mortarboard"></i> Kelas <b><?= htmlspecialchars($profile['nama_kelas']??'-') ?></b></p><p><i class="bi bi-calendar-check"></i> Masa bakti <b><?= htmlspecialchars($profile['tahun_ajaran']??'-') ?></b></p></article></div></section>
<section class="member-home-card member-news-card"><header><div><span>Informasi terbaru</span><h3>Pengumuman untuk OSIS</h3></div><i class="bi bi-bell"></i></header><div><?php foreach($news as $n): ?><article><small><i class="bi bi-clock"></i> <?= date('d M Y',strtotime($n['tanggal_publish'])) ?></small><h4><?= htmlspecialchars($n['judul']) ?></h4><p><?= htmlspecialchars(mb_strimwidth(strip_tags($n['isi']),0,145,'…')) ?></p></article><?php endforeach; if(!$news): ?><aside class="member-empty"><i class="bi bi-megaphone"></i><strong>Belum ada pengumuman</strong></aside><?php endif ?></div></section>
